<script setup>
import { ref,watch,computed } from 'vue';import { useRoute,useRouter,RouterLink } from 'vue-router';
import { api } from '../lib/api';import { notice } from '../lib/state';import { display,obraPath } from '../lib/format';import EditorForm from '../components/EditorForm.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),router=useRouter(),data=ref(null),detail=ref(null),error=ref(''),saving=ref(false),filter=ref('');
const module=computed(()=>route.params.module||'edp');
const titles={edp:'Estados de pago',adicionales:'Adicionales de obra',rdi:'Requerimientos de información',actividad:'Actividad',fotos:'Fotografía'};
const columns={edp:['numero','periodo','fecha','numero_factura','estado','monto_uf'],adicionales:['numero','descripcion','fecha_presentacion','estado','monto_uf','monto_aprobado_uf'],rdi:['numero','materia','fecha_envio','estado','responsable','fecha_respuesta'],actividad:['orden','descripcion','status','pct_programa','pct_actual'],fotos:['fecha','etiqueta','sector','caption']};
const base=computed(()=>`/obras/${route.params.obraId}/registros/${module.value}`);
const editing=computed(()=>route.name==='record-new'||route.name==='record-edit');
async function load(){error.value='';data.value=null;detail.value=null;try{if(editing.value)detail.value=await api.get(`${base.value}/${route.params.pk||'nuevo'}`);else data.value=await api.get(`${base.value}${filter.value?`?estado=${filter.value}`:''}`)}catch(e){error.value=e.message}}
watch(()=>[route.fullPath,filter.value],load,{immediate:true});
async function save(values){saving.value=true;try {const result=await (route.params.pk?api.put(`${base.value}/${route.params.pk}`,values):api.post(`${base.value}/nuevo`,values));notice('Registro guardado');router.push(obraPath(route.params.obraId,module.value));}catch(e){error.value=e.message;if(e.details?.form)detail.value={...detail.value,schema:e.details.form}}finally{saving.value=false}}
async function remove(){if(!confirm('¿Eliminar este registro?'))return;try{await api.del(`${base.value}/${route.params.pk}`);notice('Registro eliminado');router.push(obraPath(route.params.obraId,module.value))}catch(e){error.value=e.message}}
</script>
<template><div class="page-heading page-heading--module"><div class="page-heading__titles"><h2 class="page-title display">{{editing?(route.params.pk?'Editar':'Registrar')+' '+(titles[module]||module):titles[module]||module}}</h2><p class="page-description">Información, seguimiento y control de obra</p></div><div class="page-actions"><RouterLink v-if="!editing&&data?.editable" class="btn btn-primary" :to="obraPath(route.params.obraId,module)+'/nuevo'">+ Registrar</RouterLink><RouterLink v-if="editing" class="btn" :to="obraPath(route.params.obraId,module)">← Volver</RouterLink></div></div>
<p v-if="error" class="notice bad" role="alert">{{error}}</p>
<PageCard v-if="editing&&detail" title="Datos del registro"><EditorForm :schema="detail.schema" :disabled="!detail.editable" :saving="saving" :allow-delete="!!route.params.pk&&module!=='actividad'" @submit="save" @delete="remove"/></PageCard>
<template v-else-if="data"><nav v-if="module==='rdi'" class="pills record-filters"><button v-for="[key,label] in [['','Todas'],['pendiente','Pendientes'],['incompleta','Incompletas'],['respondida','Respondidas']]" :key="key" class="pill" :aria-current="filter===key?'page':undefined" @click="filter=key">{{label}}</button></nav>
<PageCard><div class="tbl-wrap"><table class="tbl tbl--stack"><thead><tr><th v-for="k in columns[module]" :key="k">{{k.replaceAll('_',' ')}}</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in data.results" :key="row.id"><td v-for="k in columns[module]" :key="k" :data-label="k">{{display(row[k],k)}}</td><td><RouterLink :to="obraPath(route.params.obraId,module)+'/'+row.id" class="btn btn-sm">{{data.editable?'Editar':'Ver'}}</RouterLink></td></tr><tr v-if="!data.results.length"><td :colspan="columns[module]?.length+1">No hay registros.</td></tr></tbody></table></div></PageCard></template></template>
